
'use strict';
/* ====== Dados ====== */
const KEY='pdv_loja_v1';
const LOGO='data:image/png;base64,';
const LBL={dinheiro:'Dinheiro',cartao:'Cartão',pix:'Pix'};
/* Armazenamento seguro: se o navegador bloquear, o sistema segue funcionando em memória (com aviso) */
let persist=true;const mem={};
function sget(k){if(window.desktopDataStore)return window.desktopDataStore.read(k);try{return localStorage.getItem(k);}catch(e){persist=false;return mem[k]||null;}}
function sset(k,v){if(window.desktopDataStore){window.desktopDataStore.write(k,v);return;}try{localStorage.setItem(k,v);}catch(e){persist=false;mem[k]=v;}}
const sess=(()=>{let m=null;return{
  get:()=>{try{return sessionStorage.getItem('pdv_sess');}catch(e){return m;}},
  set:v=>{m=String(v);try{sessionStorage.setItem('pdv_sess',m);}catch(e){}},
  del:()=>{m=null;try{sessionStorage.removeItem('pdv_sess');}catch(e){}}};})();
const emptyDB=()=>({loja:'',users:[],products:[],sales:[],purchases:[],cashRegisters:[],goals:{},seq:{}});
let storageError=null,db;
try{db=load();}catch(e){storageError=e;db=emptyDB();}
function load(){
  let r;
  try{r=sget(KEY);}catch(e){if(window.desktopDataStore)throw e;return emptyDB();}
  if(r){
    try{const d=JSON.parse(r);d.seq=d.seq||{};d.goals=d.goals||{};d.purchases=d.purchases||[];d.cashRegisters=d.cashRegisters||[];return d;}
    catch(e){if(window.desktopDataStore)throw new Error('Os dados locais estão corrompidos ou inválidos. Restaure um backup completo antes de continuar.');}
  }
  return emptyDB();
}
function save(){
  try{sset(KEY,JSON.stringify(db));return true;}
  catch(e){flash('Não foi possível salvar os dados.','err');return false;}
}
function safe(fn,e){e.preventDefault();Promise.resolve().then(()=>fn(e)).catch(err=>flash('Erro: '+((err&&err.message)||err),'err'));return false;}
const BANNER='<div style="background:#fff0d6;color:#7a4a00;padding:12px 18px;font-weight:700;text-align:center;border-bottom:2px solid #e0a030">Atenção: este navegador está bloqueando o armazenamento. Os dados NÃO serão guardados ao fechar a página. Abra o arquivo diretamente no Google Chrome ou Edge (clique duas vezes no arquivo salvo no computador).</div>';
const nextId=k=>(db.seq[k]=(db.seq[k]||0)+1);

/* ====== Utilidades ====== */
const $=s=>document.querySelector(s);
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brl=c=>(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const dt=iso=>new Date(iso).toLocaleString('pt-BR');
const money2input=c=>(c/100).toFixed(2).replace('.',',');
function parseMoney(s){
  s=String(s).trim().replace(/[R$\s]/g,'');if(!s)return NaN;
  if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');
  const n=Number(s);return isFinite(n)&&n>=0?Math.round(n*100):NaN;
}
const pad2=n=>String(n).padStart(2,'0');
const dstr=d=>`${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`;
const isAdmin=()=>!!S.user&&S.user.role==='admin';
let actx=null;
function beep(ok){try{actx=actx||new(window.AudioContext||window.webkitAudioContext)();const o=actx.createOscillator();o.frequency.value=ok?900:200;o.connect(actx.destination);o.start();setTimeout(()=>o.stop(),ok?70:300);}catch(e){}}
function flash(msg,type){
  const el=document.createElement('div');el.className=type==='err'?'err':'ok';el.textContent=msg;
  $('#toast').appendChild(el);setTimeout(()=>el.remove(),type==='err'?5000:2500);
}
let modalOpen=false;
function openModal(html){modalOpen=true;$('#modal').innerHTML=`<div class="overlay"><div class="dialog">${html}</div></div>`;}
function closeModal(){modalOpen=false;$('#modal').innerHTML='';if(S.tab==='caixa'&&$('#scan'))$('#scan').focus();}

/* ====== Senhas (PBKDF2 com sal; alternativa SHA-256 iterado) ====== */
const K=[],H0=[];
(function(){let n=2,c=0;while(c<64){let p=true;for(let d=2;d*d<=n;d++)if(n%d===0){p=false;break;}
  if(p){K.push(Math.floor((Math.cbrt(n)%1)*4294967296));if(c<8)H0.push(Math.floor((Math.sqrt(n)%1)*4294967296));c++;}n++;}})();
function sha256(msg){
  const bytes=new TextEncoder().encode(msg),l=bytes.length,w=new Uint32Array(64);
  const buf=new Uint8Array(((l+9+63)>>6)<<6);buf.set(bytes);buf[l]=0x80;
  const dv=new DataView(buf.buffer);dv.setUint32(buf.length-4,(l*8)>>>0);dv.setUint32(buf.length-8,Math.floor(l*8/4294967296));
  let h=H0.slice();
  for(let o=0;o<buf.length;o+=64){
    for(let i=0;i<16;i++)w[i]=dv.getUint32(o+i*4);
    for(let i=16;i<64;i++){const a=w[i-15],b=w[i-2];
      const s0=((a>>>7)|(a<<25))^((a>>>18)|(a<<14))^(a>>>3);
      const s1=((b>>>17)|(b<<15))^((b>>>19)|(b<<13))^(b>>>10);
      w[i]=(w[i-16]+s0+w[i-7]+s1)|0;}
    let [a,b,c,d,e,f,g,hh]=h;
    for(let i=0;i<64;i++){
      const S1=((e>>>6)|(e<<26))^((e>>>11)|(e<<21))^((e>>>25)|(e<<7));
      const ch=(e&f)^(~e&g);const t1=(hh+S1+ch+K[i]+w[i])|0;
      const S0=((a>>>2)|(a<<30))^((a>>>13)|(a<<19))^((a>>>22)|(a<<10));
      const mj=(a&b)^(a&c)^(b&c);const t2=(S0+mj)|0;
      hh=g;g=f;f=e;e=(d+t1)|0;d=c;c=b;b=a;a=(t1+t2)|0;}
    const v=[a,b,c,d,e,f,g,hh];h=h.map((x,i)=>(x+v[i])|0);
  }
  return h.map(x=>(x>>>0).toString(16).padStart(8,'0')).join('');
}
const hasSubtle=()=>!!(window.crypto&&crypto.subtle);
const toHex=u8=>[...u8].map(x=>x.toString(16).padStart(2,'0')).join('');
function randHex(n){const a=new Uint8Array(n);crypto.getRandomValues(a);return toHex(a);}
async function hashPw(pw,salt,alg){
  if(alg==='p'){
    if(!hasSubtle())throw new Error('sem suporte');
    const enc=new TextEncoder();
    const k=await crypto.subtle.importKey('raw',enc.encode(pw),'PBKDF2',false,['deriveBits']);
    const b=await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:150000,hash:'SHA-256'},k,256);
    return toHex(new Uint8Array(b));
  }
  let h=salt+pw;for(let i=0;i<3000;i++)h=sha256(h+salt+pw);return h;
}
async function setPw(u,pw){u.salt=randHex(16);u.alg=hasSubtle()?'p':'j';u.hash=await hashPw(pw,u.salt,u.alg);}

/* ====== Estado e telas gerais ====== */
const S={user:null,tab:'caixa',cart:[],pay:null,editProd:null,editUser:null,prodQ:'',vf:null,purchaseDraft:[],purchaseSaving:false};
const TABS=[['caixa','Caixa'],['produtos','Produtos e estoque'],['vendas','Vendas'],['metas','Metas'],['func','Usuários'],['compras','Compras de funcionários'],['backup','Backup']];

function render(){
  if(storageError){$('#app').innerHTML=`<div class="center"><div class="card"><h2>Falha ao carregar os dados locais</h2><p>${esc(storageError.message||storageError)}</p><p class="muted">O aplicativo não alterou os dados. Corrija o arquivo de dados ou restaure um backup completo.</p></div></div>`;return;}
  try{render0();}catch(e){$("#app").innerHTML='<div class="center"><div class="card"><h2>Erro ao abrir o sistema</h2><p>'+esc(e&&e.message||e)+'</p></div></div>';}
  if(!persist)$("#app").insertAdjacentHTML("afterbegin",BANNER);
}
function render0(){
  const app=$('#app');
  if(!db.users.length){app.innerHTML=setupHTML();$('#sl').focus();return;}
  S.user=db.users.find(u=>String(u.id)===sess.get()&&u.ativo)||null;
  if(!S.user){app.innerHTML=loginHTML();$('#lu').focus();return;}
  if(!isAdmin())S.tab='caixa';
  const tabs=isAdmin()?`<nav>${TABS.map(([k,n])=>`<button class="${S.tab===k?'act':''}" onclick="go('${k}')">${n}</button>`).join('')}</nav>`:'<nav></nav>';
  app.innerHTML=`<header><div class="brand"><img class="logo-h" src="${LOGO}" alt="${esc(db.loja)}"></div>${tabs}
    <div class="who"><span>${esc(S.user.nome)} · ${isAdmin()?'Administrador':'Vendedor'}</span><button class="btn sm" onclick="logout()">Sair</button></div></header><main id="content"></main>`;
  renderTab();
}
function renderTab(){
  const c=$('#content');if(!c)return;const t=S.tab;
  if(t==='caixa'){c.innerHTML=caixaHTML();renderCashRegister();renderCart();$('#scan').focus();}
  else if(!isAdmin())return;
  else if(t==='produtos'){c.innerHTML=produtosHTML();renderPList();}
  else if(t==='vendas')c.innerHTML=vendasHTML();
  else if(t==='metas')c.innerHTML=metasHTML();
  else if(t==='func')c.innerHTML=funcHTML();
  else if(t==='compras')c.innerHTML=comprasFuncionariosHTML();
  else if(t==='backup')c.innerHTML=backupHTML();
}
function go(t){if(!isAdmin()&&t!=='caixa')return;S.tab=t;S.editProd=null;S.editUser=null;render();}

function setupHTML(){return `<div class="center"><div class="card"><img class="logo-l" src="${LOGO}" alt="Logo"><h2>Primeiro acesso</h2>
  <p class="muted">Crie o usuário administrador (dono da loja).</p>
  <form onsubmit="return safe(doSetup,event)">
  <label>Nome da loja<input id="sl" required></label>
  <label>Seu nome<input id="sn" required></label>
  <label>Usuário (login)<input id="su" required autocomplete="off"></label>
  <label>Senha (mínimo 6 caracteres)<input id="sp" type="password" required></label>
  <label>Confirmar senha<input id="sc" type="password" required></label>
  <button class="btn primary lg">Criar e entrar</button></form></div></div>`;}
async function doSetup(e){
  e.preventDefault();
  const loja=$('#sl').value.trim(),nome=$('#sn').value.trim(),usuario=$('#su').value.trim().toLowerCase(),p=$('#sp').value;
  if(/\s/.test(usuario))return flash('O usuário não pode ter espaços.','err');
  if(p.length<6)return flash('A senha deve ter pelo menos 6 caracteres.','err');
  if(p!==$('#sc').value)return flash('As senhas não conferem.','err');
  const u={id:nextId('user'),nome,usuario,role:'admin',ativo:true};
  await setPw(u,p);db.loja=loja;db.users.push(u);
  if(!save())return;
  sess.set(u.id);S.tab='caixa';render();return false;
}
function loginHTML(){return `<div class="center"><div class="card"><img class="logo-l" src="${LOGO}" alt="${esc(db.loja)}">
  <p class="muted">Entre com seu usuário e senha.</p>
  <form onsubmit="return safe(doLogin,event)">
  <label>Usuário<input id="lu" required autocomplete="username"></label>
  <label>Senha<input id="lp" type="password" required autocomplete="current-password"></label>
  <button class="btn primary lg">Entrar</button></form></div></div>`;}
let fails=0,lock=0;
async function doLogin(e){
  e.preventDefault();const now=Date.now();
  if(now<lock)return flash(`Muitas tentativas. Aguarde ${Math.ceil((lock-now)/1000)}s.`,'err');
  const u=db.users.find(x=>x.usuario===$('#lu').value.trim().toLowerCase());
  let ok=false;
  if(u&&u.ativo){try{ok=(await hashPw($('#lp').value,u.salt,u.alg))===u.hash;}catch(err){}}
  if(!ok){fails++;if(fails>=5){lock=Date.now()+30000;fails=0;}return flash('Usuário ou senha incorretos.','err');}
  fails=0;sess.set(u.id);S.tab='caixa';S.cart=[];render();return false;
}
function logout(){sess.del();S.cart=[];S.user=null;S.tab='caixa';render();}

/* ====== Caixa ====== */
const P=id=>db.products.find(p=>p.id===id);
const cartTotal=()=>S.cart.reduce((a,i)=>{const p=P(i.id);return a+(p?p.preco*i.qtd:0);},0);
function caixaHTML(){return `<div class="caixa"><section>
  <div id="cashRegister"></div>
  <div class="card"><label for="scan">Código de barras — bipe o produto</label>
    <div class="row" style="margin-top:6px"><input id="scan" autocomplete="off" placeholder="Aguardando leitura..." onkeydown="if(event.key==='Enter'){event.preventDefault();scan();}">
    <label style="width:105px;flex-shrink:0">Quantidade<input id="scanQty" type="number" min="1" step="1" value="1" inputmode="numeric" onkeydown="if(event.key==='Enter'){event.preventDefault();$('#scan').focus();scan();}"></label>
    <button class="btn primary" onclick="scan()">Adicionar</button></div>
    <div style="margin-top:12px"><label>Adicionar sem código (buscar pelo nome)
    <input id="busca" autocomplete="off" placeholder="Digite o nome do produto" oninput="buscar()" onkeydown="if(event.key==='Enter'){event.preventDefault();buscarEnter();}"></label>
    <div id="resultados" class="results"></div></div></div>
  <div class="card"><table><thead><tr><th>Produto</th><th class="num">Preço</th><th>Qtd.</th><th class="num">Subtotal</th><th></th></tr></thead><tbody id="cartbody"></tbody></table></div>
  </section><aside><div class="card total"><div class="muted" style="font-weight:700">TOTAL DA COMPRA</div>
    <div id="total" class="big">R$ 0,00</div><div id="count" class="muted"></div>
    <button class="btn primary lg" onclick="openPay()">Finalizar venda (F2)</button>
    <button class="btn" style="width:100%" onclick="limparVenda()">Cancelar venda</button>
    ${!isAdmin()?'<button class="btn" style="width:100%" onclick="openEmployeePurchase()">Registrar compra pessoal</button>':''}</div></aside></div>`;}
function currentCashRegister(){return db.cashRegisters.find(register=>!register.closedAt)||null;}
function cashRegisterSales(register){
  return db.sales.filter(s=>String(s.cashRegisterId)===String(register.id)&&s.status==='finalizada');
}
function cashSaleAmount(s){
  if(s.pagamentos)return s.pagamentos.dinheiro||0;
  return s.pagamento==='dinheiro'?s.total:0;
}
function cashRegisterExpected(register){
  return register.openingAmount+cashRegisterSales(register).reduce((sum,s)=>sum+cashSaleAmount(s),0);
}
function renderCashRegister(){
  const el=$('#cashRegister');if(!el)return;
  const register=currentCashRegister();
  if(register){
    const sales=cashRegisterSales(register),cashSales=sales.reduce((sum,s)=>sum+cashSaleAmount(s),0);
    el.innerHTML=`<div class="card"><h2>Caixa aberto</h2>
      <p class="muted">Aberto por ${esc(register.openedByName)} · ${dt(register.openedAt)}</p>
      <div class="stats"><div class="stat"><small>Valor de abertura</small><b>${brl(register.openingAmount)}</b></div>
        <div class="stat"><small>Vendas em dinheiro</small><b>${brl(cashSales)}</b></div>
        <div class="stat"><small>Saldo esperado no caixa</small><b>${brl(cashRegisterExpected(register))}</b></div>
        <div class="stat"><small>Vendas no turno</small><b>${sales.length}</b></div></div>
      <button class="btn danger" onclick="closeCashRegister()">Fechar caixa</button>
    </div>`;
    return;
  }
  const last=[...db.cashRegisters].sort((a,b)=>new Date(b.closedAt||b.openedAt)-new Date(a.closedAt||a.openedAt))[0];
  el.innerHTML=`<div class="card"><h2>Caixa fechado</h2>
    ${last?`<p class="muted">Último fechamento: ${dt(last.closedAt)} · Saldo esperado: <b>${brl(last.closingAmount)}</b></p>`:'<p class="muted">Ainda não há abertura registrada. Vendas continuam permitidas e ficarão fora do fechamento.</p>'}
    <form class="formgrid" onsubmit="return openCashRegister(event)">
      <label>Valor inicial do caixa (R$)<input id="cashOpeningAmount" required inputmode="decimal" autocomplete="off" value="0,00"></label>
      <div class="actions" style="margin:0"><button class="btn primary">Abrir caixa</button></div>
    </form>
  </div>`;
}
function openCashRegister(e){
  e.preventDefault();
  if(!S.user||!S.user.ativo)return flash('Entre com um usuário ativo para abrir o caixa.','err'),false;
  if(currentCashRegister())return flash('O caixa já está aberto.','err'),false;
  const openingAmount=parseMoney($('#cashOpeningAmount').value);
  if(isNaN(openingAmount))return flash('Informe um valor inicial válido.','err'),false;
  const id=nextId('cashRegister');
  const register={id,openedAt:new Date().toISOString(),openedById:S.user.id,openedByName:S.user.nome,openingAmount,closedAt:null,closedById:null,closedByName:null,closingAmount:null,saleCount:0,cashSales:0};
  db.cashRegisters.push(register);
  if(!save()){db.cashRegisters.pop();db.seq.cashRegister--;return false;}
  flash('Caixa aberto.','ok');renderTab();return false;
}
function closeCashRegister(){
  if(!S.user||!S.user.ativo)return flash('Entre com um usuário ativo para fechar o caixa.','err');
  const register=currentCashRegister();
  if(!register)return flash('Não há caixa aberto.','err');
  const sales=cashRegisterSales(register);
  const previous={closedAt:register.closedAt,closedById:register.closedById,closedByName:register.closedByName,closingAmount:register.closingAmount,saleCount:register.saleCount,cashSales:register.cashSales};
  register.closedAt=new Date().toISOString();
  register.closedById=S.user.id;
  register.closedByName=S.user.nome;
  register.closingAmount=cashRegisterExpected(register);
  register.saleCount=sales.length;
  register.cashSales=sales.reduce((sum,s)=>sum+cashSaleAmount(s),0);
  if(!save()){Object.assign(register,previous);return;}
  flash(`Caixa fechado. Saldo esperado: ${brl(register.closingAmount)}.`,'ok');renderTab();
}
function renderCart(){
  S.cart=S.cart.filter(i=>P(i.id));
  const b=$('#cartbody');if(!b)return;
  b.innerHTML=S.cart.length?S.cart.map(i=>{const p=P(i.id);return `<tr><td><b>${esc(p.nome)}</b><br><small>${esc(p.codigo)}</small></td>
    <td class="num">${brl(p.preco)}</td>
    <td><div class="qty"><button onclick="chg(${p.id},-1)">−</button><input value="${i.qtd}" inputmode="numeric" onchange="setQty(${p.id},this.value)" onfocus="this.select()"><button onclick="chg(${p.id},1)">+</button></div></td>
    <td class="num"><b>${brl(p.preco*i.qtd)}</b></td><td class="num"><button class="btn sm danger" onclick="rm(${p.id})">Remover</button></td></tr>`;}).join('')
    :'<tr><td colspan="5" class="muted" style="text-align:center;padding:30px">Bipe um produto para começar a venda.</td></tr>';
  $('#total').textContent=brl(cartTotal());
  const n=S.cart.reduce((a,i)=>a+i.qtd,0);$('#count').textContent=n?`${n} ${n===1?'item':'itens'}`:'';
}
function scan(){
  const inp=$('#scan'),qtyInput=$('#scanQty');const code=inp.value.trim(),q=Number(qtyInput.value);inp.value='';inp.focus();if(!code)return;
  if(!Number.isInteger(q)||q<1){beep(false);return flash('Informe uma quantidade inteira maior que zero.','err');}
  const p=db.products.find(x=>x.codigo===code);
  if(!p){beep(false);return flash(`Código de barras não encontrado: ${code}`,'err');}
  if(addToCart(p,q))qtyInput.value='1';
}
function addToCart(p,q){
  if(!p||!Number.isInteger(q)||q<1)return false;
  const it=S.cart.find(i=>i.id===p.id);const novo=(it?it.qtd:0)+q;
  if(novo>p.estoque){beep(false);flash(`Estoque insuficiente de "${p.nome}". Disponível: ${p.estoque}`,'err');return false;}
  if(it)it.qtd=novo;else S.cart.push({id:p.id,qtd:q});
  beep(true);renderCart();return true;
}
function setQty(id,v){
  const p=P(id),it=S.cart.find(i=>i.id===id);if(!p||!it)return;
  let n=parseInt(v,10);if(isNaN(n)||n<1)n=1;
  if(n>p.estoque){flash(`Estoque insuficiente de "${p.nome}". Disponível: ${p.estoque}`,'err');n=it.qtd;}
  it.qtd=n;renderCart();$('#scan').focus();
}
function chg(id,d){const it=S.cart.find(i=>i.id===id);if(it)setQty(id,it.qtd+d);}
function rm(id){S.cart=S.cart.filter(i=>i.id!==id);renderCart();$('#scan').focus();}
function limparVenda(){if(!S.cart.length)return;if(confirm('Cancelar esta venda e remover todos os itens?')){S.cart=[];renderCart();$('#scan').focus();}}
function matches(){
  const q=$('#busca').value.trim().toLowerCase();if(!q)return[];
  return db.products.filter(p=>p.nome.toLowerCase().includes(q)||p.codigo.includes(q)).slice(0,8);
}
function buscar(){
  const m=matches();
  $('#resultados').innerHTML=m.map(p=>`<button onclick="pick(${p.id})"><span>${esc(p.nome)} <small>(${p.estoque} em estoque)</small></span><b>${brl(p.preco)}</b></button>`).join('');
}
function buscarEnter(){const m=matches();if(m.length===1)pick(m[0].id);else if(!m.length&&$('#busca').value.trim())flash('Nenhum produto encontrado.','err');}
function pick(id){addToCart(P(id),1);$('#busca').value='';$('#resultados').innerHTML='';$('#scan').focus();}

/* Pagamento */
function openPay(){
  if(!S.cart.length)return flash('Adicione ao menos um produto.','err');
  if(!db.users.some(u=>u.role==='funcionario'&&u.ativo))return flash('Cadastre ao menos um vendedor ativo na aba Usuários antes de finalizar vendas.','err');
  S.pay={m:null,vendedorId:'',amounts:{dinheiro:0,cartao:0,pix:0}};showPay();
}
function showPay(){
  const t=cartTotal(),m=S.pay.m,vendedores=db.users.filter(u=>u.role==='funcionario'&&u.ativo);
  openModal(`<h2>Finalizar venda</h2><div class="paytotal">${brl(t)}</div>
  <label style="margin-bottom:12px">Qual vendedor realizou esta venda?
    <select id="saleSeller" required onchange="S.pay.vendedorId=this.value">
      <option value="">Selecione o vendedor</option>${vendedores.map(u=>`<option value="${u.id}" ${String(S.pay.vendedorId)===String(u.id)?'selected':''}>${esc(u.nome)}</option>`).join('')}
    </select>
  </label>
  <div class="paybtns">${Object.keys(LBL).map(k=>`<button type="button" class="paybtn ${m===k?'sel':''}" onclick="selPay('${k}')">${LBL[k]}</button>`).join('')}<button type="button" class="paybtn ${m==='misto'?'sel':''}" onclick="selPay('misto')">Misto</button></div>
  ${m==='misto'?`<div class="formgrid">${Object.keys(LBL).map(k=>`<label>${LBL[k]} (R$)<input id="pay_${k}" inputmode="decimal" autocomplete="off" value="${money2input(S.pay.amounts[k]||0)}" oninput="updateMixedAmount('${k}',this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault();if(!$('#confirmBtn').disabled)confirmSale();}"></label>`).join('')}</div>
  <p id="paymentBalance" class="muted"></p>
  ${S.pay.amounts.dinheiro>0?`<label>Dinheiro recebido (R$)<input id="rec" inputmode="decimal" autocomplete="off" value="${money2input(S.pay.received||S.pay.amounts.dinheiro)}" oninput="S.pay.received=parseMoney(this.value);calcTroco()" onkeydown="if(event.key==='Enter'){event.preventDefault();if(!$('#confirmBtn').disabled)confirmSale();}"></label>
  <div class="quick"><button type="button" class="btn sm" onclick="setRec(${S.pay.amounts.dinheiro})">Dinheiro exato</button></div>`:''}
  <div id="troco" class="troco"></div>`:m==='dinheiro'?`<label>Valor recebido (R$)<input id="rec" inputmode="decimal" autocomplete="off" oninput="calcTroco()" onkeydown="if(event.key==='Enter'){event.preventDefault();if(!$('#confirmBtn').disabled)confirmSale();}"></label>
  <div class="quick"><button type="button" class="btn sm" onclick="setRec(${t})">Valor exato</button>${[20,50,100].map(v=>`<button type="button" class="btn sm" onclick="setRec(${v*100})">R$ ${v}</button>`).join('')}</div>
  <div id="troco" class="troco"></div>`:''}
  <div class="actions"><button class="btn" onclick="closeModal()">Voltar</button><button id="confirmBtn" class="btn primary" onclick="confirmSale()" disabled>Confirmar venda</button></div>`);
  calcTroco();
}
function selPay(m){
  S.pay.m=m;
  if(m==='misto'&&!Object.values(S.pay.amounts).some(v=>v>0))S.pay.amounts.dinheiro=cartTotal();
  showPay();if(m==='dinheiro')$('#rec').focus();else if(m==='misto')$('#pay_dinheiro').focus();else $('#confirmBtn').focus();
}
function setRec(c){$('#rec').value=money2input(c);if(S.pay.m==='misto')S.pay.received=c;calcTroco();$('#rec').focus();}
function updateMixedAmount(method,value){
  const amount=parseMoney(value);
  S.pay.amounts[method]=isNaN(amount)?0:amount;
  if(method==='dinheiro'&&S.pay.received!=null&&S.pay.received<S.pay.amounts.dinheiro)S.pay.received=S.pay.amounts.dinheiro;
  calcTroco();
}
function calcTroco(){
  const b=$('#confirmBtn');if(!b)return;const m=S.pay.m,t=cartTotal();
  let valid=!!m&&!!S.pay.vendedorId;
  if(m==='dinheiro'){
    const box=$('#troco'),r=parseMoney($('#rec').value);
    if(isNaN(r)){box.className='troco';box.textContent='Informe o valor recebido';valid=false;}
    else if(r<t){box.className='troco bad';box.innerHTML=`Faltam <b>${brl(t-r)}</b>`;valid=false;}
    else{box.className='troco good';box.innerHTML=`Troco: <b>${brl(r-t)}</b>`;}
  }else if(m==='misto'){
    const total=Object.values(S.pay.amounts).reduce((sum,value)=>sum+value,0),dinheiro=S.pay.amounts.dinheiro;
    const balance=$('#paymentBalance'),box=$('#troco');
    if(balance)balance.textContent=`Dividido: ${brl(total)} de ${brl(t)}${total<t?' — faltam '+brl(t-total):total>t?' — excede '+brl(total-t):''}`;
    if(total!==t)valid=false;
    if(dinheiro>0){
      const rec=$('#rec')?parseMoney($('#rec').value):NaN;
      if(isNaN(rec)||rec<dinheiro){if(box){box.className='troco bad';box.textContent='Informe o dinheiro recebido, igual ou maior que a parte em dinheiro.';}valid=false;}
      else if(box){box.className='troco good';box.innerHTML=`Troco: <b>${brl(rec-dinheiro)}</b>`;}
    }else if(box){box.className='troco';box.textContent='';}
  }
  b.disabled=!valid;
}
function confirmSale(){
  const m=S.pay&&S.pay.m;if(!m)return;
  const vendedor=db.users.find(u=>String(u.id)===String(S.pay.vendedorId)&&u.role==='funcionario'&&u.ativo);
  if(!vendedor)return flash('Selecione um vendedor ativo para esta venda.','err');
  let pagamentos,rec=null,troco=null;
  if(m==='misto'){
    pagamentos=Object.fromEntries(Object.keys(LBL).map(k=>[k,S.pay.amounts[k]||0]));
    if(Object.values(pagamentos).reduce((sum,value)=>sum+value,0)!==cartTotal())return flash('A soma dos pagamentos deve ser exatamente igual ao total da venda.','err');
    if(pagamentos.dinheiro>0){rec=parseMoney($('#rec').value);if(isNaN(rec)||rec<pagamentos.dinheiro)return flash('O valor recebido em dinheiro não pode ser menor que a parte paga em dinheiro.','err');troco=rec-pagamentos.dinheiro;}
  }else if(m==='dinheiro'){
    rec=parseMoney($('#rec').value);if(isNaN(rec)||rec<cartTotal())return flash('Valor recebido menor que o total.','err');troco=rec-cartTotal();
    pagamentos={dinheiro:cartTotal(),cartao:0,pix:0};
  }else pagamentos={[m]:cartTotal(),dinheiro:0,cartao:0,pix:0};
  const itens=[];let total=0;
  for(const it of S.cart){
    const p=P(it.id);
    if(!p){flash('Um produto foi removido do cadastro.','err');closeModal();renderCart();return;}
    if(it.qtd>p.estoque){flash(`Estoque insuficiente de "${p.nome}". Disponível: ${p.estoque}`,'err');closeModal();renderCart();return;}
    itens.push({id:p.id,nome:p.nome,codigo:p.codigo,preco:p.preco,qtd:it.qtd});total+=p.preco*it.qtd;
  }
  if(Object.values(pagamentos).reduce((sum,value)=>sum+value,0)!==total)return flash('A soma dos pagamentos deve ser igual ao total da venda.','err');
  const cashRegister=currentCashRegister();
  const sale={id:nextId('sale'),data:new Date().toISOString(),vendedorId:vendedor.id,vendedorNome:vendedor.nome,cashRegisterId:cashRegister?cashRegister.id:null,itens,total,pagamento:m,pagamentos,recebido:rec,troco,status:'finalizada'};
  itens.forEach(i=>{P(i.id).estoque-=i.qtd;});db.sales.push(sale);
  if(!save()){closeModal();renderCart();return;}
  S.cart=[];S.pay=null;renderCart();renderCashRegister();showReceipt(sale.id,true);
}

/* Comprovante */
function receiptHTML(s){
  const pagamentos=s.pagamentos||{[s.pagamento]:s.total};
  const pagamentoHTML=Object.keys(LBL).filter(k=>pagamentos[k]>0).map(k=>`<div class="r"><span>${LBL[k]}</span><span>${brl(pagamentos[k])}</span></div>`).join('');
  return `<div class="rc"><div class="h">${esc(db.loja)}</div><div class="c">COMPROVANTE DE VENDA</div><div class="c">Documento sem valor fiscal</div><hr>
  <div>Venda nº ${String(s.id).padStart(6,'0')}</div><div>${dt(s.data)}</div><div>Vendedor: ${esc(s.vendedorNome)}</div><hr>
  ${s.itens.map(i=>`<div class="it"><div>${esc(i.nome)}</div><div class="r"><span>${i.qtd} x ${brl(i.preco)}</span><span>${brl(i.preco*i.qtd)}</span></div></div>`).join('')}<hr>
  <div class="r t"><span>TOTAL</span><span>${brl(s.total)}</span></div>
  <div><b>Pagamento${s.pagamento==='misto'?'s':''}</b></div>${pagamentoHTML}
  ${pagamentos.dinheiro>0?`<div class="r"><span>Dinheiro recebido</span><span>${brl(s.recebido==null?pagamentos.dinheiro:s.recebido)}</span></div><div class="r"><span>Troco</span><span>${brl(s.troco||0)}</span></div>`:''}
  ${s.status==='cancelada'?'<hr><div class="c"><b>*** VENDA CANCELADA ***</b></div>':''}
  <hr><div class="c">Obrigado pela preferência!</div></div>`;
}
function showReceipt(id,nova){
  const s=db.sales.find(x=>x.id===id);
  openModal(`${nova?`<div class="troco ${s.troco?'good':''}" style="margin:0 0 12px">${s.troco?`Troco: <b>${brl(s.troco)}</b>`:'Venda concluída!'}</div>`:''}
  ${receiptHTML(s)}
  <div class="actions" style="justify-content:center"><button class="btn primary" onclick="printReceipt(${id})">Imprimir comprovante</button>
  ${!nova&&isAdmin()&&s.status==='finalizada'?`<button class="btn danger" onclick="cancelSale(${id})">Cancelar venda</button>`:''}
  <button class="btn" onclick="closeModal()">${nova?'Nova venda':'Fechar'}</button></div>`);
}
function printReceipt(id){$('#print-area').innerHTML=receiptHTML(db.sales.find(x=>x.id===id));window.print();}
function cancelSale(id){
  if(!isAdmin())return;const s=db.sales.find(x=>x.id===id);
  if(!s||s.status!=='finalizada')return;
  if(!confirm(`Cancelar a venda nº ${s.id}? Os produtos voltarão ao estoque e ela deixará de contar nas metas.`))return;
  s.status='cancelada';s.itens.forEach(i=>{const p=P(i.id);if(p)p.estoque+=i.qtd;});
  if(!save())return;closeModal();flash('Venda cancelada.','ok');renderTab();
}

/* ====== Produtos (admin) ====== */
function produtosHTML(){
  const p=S.editProd?P(S.editProd):null;
  return `<div class="card"><h2>${p?'Editar produto':'Novo produto'}</h2><form class="formgrid" onsubmit="return saveProd(event)">
  <label>Nome<input id="pn" required autocomplete="off" value="${esc(p&&p.nome)}"></label>
  <label>Código de barras<input id="pc" required autocomplete="off" value="${esc(p&&p.codigo)}" onkeydown="if(event.key==='Enter'){event.preventDefault();$('#pp').focus();}"></label>
  <label>Preço (R$)<input id="pp" required inputmode="decimal" autocomplete="off" value="${p?money2input(p.preco):''}"></label>
  <label>Quantidade em estoque<input id="pe" required type="number" min="0" step="1" value="${p?p.estoque:''}"></label>
  <div class="actions" style="margin:0"><button class="btn primary">Salvar produto</button>${p?'<button type="button" class="btn" onclick="S.editProd=null;renderTab()">Cancelar</button>':''}</div></form></div>
  <div class="card"><div style="margin-bottom:10px"><input id="pq" style="width:100%;max-width:380px" placeholder="Buscar por nome ou código" value="${esc(S.prodQ)}" oninput="S.prodQ=this.value;renderPList()"></div>
  <table><thead><tr><th>Produto</th><th>Código</th><th class="num">Preço</th><th class="num">Estoque</th><th></th></tr></thead><tbody id="plist"></tbody></table></div>`;
}
function renderPList(){
  const q=S.prodQ.trim().toLowerCase();
  const l=db.products.filter(p=>!q||p.nome.toLowerCase().includes(q)||p.codigo.includes(q)).sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR'));
  $('#plist').innerHTML=l.length?l.map(p=>`<tr><td><b>${esc(p.nome)}</b></td><td>${esc(p.codigo)}</td><td class="num">${brl(p.preco)}</td>
  <td class="num">${p.estoque===0?'<span class="tag bad">SEM ESTOQUE</span>':p.estoque<=5?`<span class="tag warn">${p.estoque} (baixo)</span>`:p.estoque}</td>
  <td class="num"><button class="btn sm" onclick="editProd(${p.id})">Editar</button> <button class="btn sm danger" onclick="delProd(${p.id})">Excluir</button></td></tr>`).join('')
  :'<tr><td colspan="5" class="muted" style="text-align:center;padding:24px">Nenhum produto cadastrado.</td></tr>';
}
function saveProd(e){
  e.preventDefault();if(!isAdmin())return false;
  const nome=$('#pn').value.trim(),codigo=$('#pc').value.trim(),preco=parseMoney($('#pp').value),est=parseInt($('#pe').value,10);
  if(!nome||!codigo)return flash('Preencha nome e código de barras.','err'),false;
  if(isNaN(preco)||preco<=0)return flash('Informe um preço válido (ex.: 12,90).','err'),false;
  if(isNaN(est)||est<0)return flash('Informe uma quantidade de estoque válida.','err'),false;
  if(db.products.some(p=>p.codigo===codigo&&p.id!==S.editProd))return flash('Já existe um produto com este código de barras.','err'),false;
  if(S.editProd){const p=P(S.editProd);Object.assign(p,{nome,codigo,preco,estoque:est});}
  else db.products.push({id:nextId('prod'),nome,codigo,preco,estoque:est});
  if(!save())return false;
  flash('Produto salvo.','ok');S.editProd=null;renderTab();$('#pn').focus();return false;
}
function editProd(id){S.editProd=id;renderTab();window.scrollTo(0,0);}
function delProd(id){
  if(!isAdmin())return;const p=P(id);
  if(!confirm(`Excluir "${p.nome}"? O histórico de vendas será mantido.`))return;
  db.products=db.products.filter(x=>x.id!==id);if(save())renderPList();
}

/* ====== Vendas (admin) ====== */
function vendasHTML(){
  const t=dstr(new Date());S.vf=S.vf||{de:t,ate:t,vend:''};const f=S.vf;
  const l=db.sales.filter(s=>{const d=dstr(new Date(s.data));return d>=f.de&&d<=f.ate&&(!f.vend||String(s.vendedorId)===f.vend);}).sort((a,b)=>b.id-a.id);
  const ok=l.filter(s=>s.status==='finalizada');
  const tot=ok.reduce((a,s)=>a+s.total,0);
  const por=k=>ok.reduce((sum,s)=>sum+(s.pagamentos?s.pagamentos[k]||0:(s.pagamento===k?s.total:0)),0);
  const vend=db.users.filter(u=>u.role==='funcionario'||u.role==='admin');
  return `<div class="card"><div class="formgrid">
  <label>De<input type="date" id="vd" value="${f.de}" onchange="setVF()"></label>
  <label>Até<input type="date" id="va" value="${f.ate}" onchange="setVF()"></label>
  <label>Vendedor<select id="vv" onchange="setVF()"><option value="">Todos</option>${vend.map(u=>`<option value="${u.id}" ${f.vend===String(u.id)?'selected':''}>${esc(u.nome)}</option>`).join('')}</select></label></div></div>
  <div class="stats"><div class="stat"><small>Total vendido</small><b style="color:var(--pri)">${brl(tot)}</b></div><div class="stat"><small>Vendas finalizadas</small><b>${ok.length}</b></div>
  <div class="stat"><small>Dinheiro</small><b>${brl(por('dinheiro'))}</b></div><div class="stat"><small>Cartão</small><b>${brl(por('cartao'))}</b></div><div class="stat"><small>Pix</small><b>${brl(por('pix'))}</b></div></div>
  <div class="card"><table><thead><tr><th>Nº</th><th>Data e hora</th><th>Vendedor</th><th>Itens</th><th>Pagamento</th><th class="num">Total</th><th>Situação</th><th></th></tr></thead><tbody>
  ${l.length?l.map(s=>`<tr style="${s.status==='cancelada'?'opacity:.55':''}"><td>${s.id}</td><td>${dt(s.data)}</td><td>${esc(s.vendedorNome)}</td><td>${s.itens.reduce((a,i)=>a+i.qtd,0)}</td><td>${s.pagamento==='misto'?Object.keys(LBL).filter(k=>(s.pagamentos&&s.pagamentos[k]>0)).map(k=>`${LBL[k]} ${brl(s.pagamentos[k])}`).join(' + '):LBL[s.pagamento]}</td>
  <td class="num"><b>${brl(s.total)}</b></td><td>${s.status==='finalizada'?'<span class="tag ok">Finalizada</span>':'<span class="tag bad">Cancelada</span>'}</td>
  <td class="num"><button class="btn sm" onclick="showReceipt(${s.id})">Ver</button></td></tr>`).join(''):'<tr><td colspan="8" class="muted" style="text-align:center;padding:24px">Nenhuma venda no período.</td></tr>'}
  </tbody></table></div>`;
}
function setVF(){S.vf={de:$('#vd').value,ate:$('#va').value,vend:$('#vv').value};renderTab();}

/* ====== Metas (admin) ====== */
function periodo(tipo){
  const n=new Date();let ini,fim;
  if(tipo==='semanal'){const d=(n.getDay()+6)%7;ini=new Date(n.getFullYear(),n.getMonth(),n.getDate()-d);fim=new Date(ini.getFullYear(),ini.getMonth(),ini.getDate()+7);}
  else{ini=new Date(n.getFullYear(),n.getMonth(),1);fim=new Date(n.getFullYear(),n.getMonth()+1,1);}
  return {ini,fim};
}
const vendidoPeriodo=(uid,p)=>db.sales.filter(s=>s.status==='finalizada'&&s.vendedorId===uid&&new Date(s.data)>=p.ini&&new Date(s.data)<p.fim).reduce((a,s)=>a+s.total,0);
const dm=d=>`${pad2(d.getDate())}/${pad2(d.getMonth()+1)}`;
function metasHTML(){
  const vs=db.users.filter(u=>u.role==='funcionario'&&u.ativo);
  if(!vs.length)return '<div class="card muted">Cadastre vendedores na aba "Usuários" para definir metas.</div>';
  return `<p class="muted" style="margin-top:0">A meta é renovada a cada período: semanal (segunda a domingo) ou mensal (mês corrente). Contam apenas vendas finalizadas.</p><div class="mgrid4">`+vs.map(u=>{
    const g=db.goals[u.id];
    if(!g)return `<div class="mcard"><div class="mh"><b>${esc(u.nome)}</b><button class="btn sm primary" onclick="editMeta(${u.id})">Definir meta</button></div><div class="muted">Sem meta definida.</div></div>`;
    const per=periodo(g.periodo),vend=vendidoPeriodo(u.id,per),falta=Math.max(0,g.valor-vend),ok=vend>=g.valor;
    const pct=Math.floor(vend*1000/g.valor)/10;
    const fimDia=new Date(per.fim.getFullYear(),per.fim.getMonth(),per.fim.getDate()-1);
    return `<div class="mcard ${ok?'ok':''}"><div class="mh"><b>${esc(u.nome)}</b><button class="btn sm" onclick="editMeta(${u.id})">Alterar meta</button></div>
    <div class="muted">Meta ${g.periodo} · ${dm(per.ini)} a ${dm(fimDia)}</div>
    <div class="mg"><div><small>Meta</small><b>${brl(g.valor)}</b></div><div><small>Vendido</small><b>${brl(vend)}</b></div><div><small>Falta</small><b>${brl(falta)}</b></div><div><small>Atingido</small><b>${String(pct).replace('.',',')}%</b></div></div>
    <div class="bar"><i style="width:${Math.min(100,pct)}%"></i></div>${ok?'<div class="atingida">✔ META ATINGIDA</div>':''}</div>`;}).join('')+'</div>';
}
function editMeta(uid){
  const u=db.users.find(x=>x.id===uid),g=db.goals[uid];
  openModal(`<h2>Meta de ${esc(u.nome)}</h2><form onsubmit="return saveMeta(event,${uid})">
  <label style="margin-bottom:12px">Valor da meta (R$)<input id="mv" required inputmode="decimal" autocomplete="off" value="${g?money2input(g.valor):''}"></label>
  <label>Período<select id="mp"><option value="mensal" ${g&&g.periodo==='mensal'?'selected':''}>Mensal</option><option value="semanal" ${g&&g.periodo==='semanal'?'selected':''}>Semanal</option></select></label>
  <div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancelar</button>${g?`<button type="button" class="btn danger" onclick="delMeta(${uid})">Remover meta</button>`:''}<button class="btn primary">Salvar</button></div></form>`);
  $('#mv').focus();
}
function saveMeta(e,uid){
  e.preventDefault();if(!isAdmin())return false;
  const v=parseMoney($('#mv').value);if(isNaN(v)||v<=0)return flash('Informe um valor de meta válido.','err'),false;
  db.goals[uid]={valor:v,periodo:$('#mp').value};if(!save())return false;
  closeModal();flash('Meta salva.','ok');renderTab();return false;
}
function delMeta(uid){if(!isAdmin())return;delete db.goals[uid];if(save()){closeModal();renderTab();}}

/* ====== Usuários (admin) ====== */
function funcHTML(){
  const u=S.editUser?db.users.find(x=>x.id===S.editUser):null;
  const l=db.users;
  return `<div class="card"><h2>${u?'Editar usuário':'Novo usuário'}</h2><form class="formgrid" onsubmit="return safe(saveUser,event)">
  <label>Nome<input id="un" required autocomplete="off" value="${esc(u&&u.nome)}"></label>
  <label>Usuário (login)<input id="uu" required autocomplete="off" value="${esc(u&&u.usuario)}"></label>
  <label>${u?'Nova senha (vazio = manter)':'Senha (mín. 6 caracteres)'}<input id="us" type="password" autocomplete="new-password" ${u?'':'required'}></label>
  <label>Perfil de acesso<select id="ur" ${u&&String(u.id)===String(S.user.id)?'disabled':''}>
    <option value="funcionario" ${!u||u.role==='funcionario'?'selected':''}>Vendedor (somente caixa)</option>
    <option value="admin" ${u&&u.role==='admin'?'selected':''}>Administrador</option>
  </select></label>
  <label>Limite mensal de compra do vendedor (R$)<input id="ul" required inputmode="decimal" autocomplete="off" value="${u&&u.limiteCompra!=null?money2input(u.limiteCompra):'0,00'}"></label>
  <div class="actions" style="margin:0"><button class="btn primary">Salvar</button>${u?'<button type="button" class="btn" onclick="S.editUser=null;renderTab()">Cancelar</button>':''}</div></form></div>
  <div class="card"><table><thead><tr><th>Nome</th><th>Usuário</th><th>Perfil</th><th>Limite mensal</th><th>Situação</th><th></th></tr></thead><tbody>
  ${l.length?l.map(x=>`<tr><td><b>${esc(x.nome)}</b></td><td>${esc(x.usuario)}</td><td>${x.role==='admin'?'Administrador':'Vendedor'}</td><td>${x.role==='funcionario'?brl(x.limiteCompra||0):'—'}</td><td>${x.ativo?'<span class="tag ok">Ativo</span>':'<span class="tag bad">Inativo</span>'}</td>
  <td class="num"><button class="btn sm" onclick="S.editUser=${x.id};renderTab();window.scrollTo(0,0)">Editar</button> <button class="btn sm" onclick="toggleUser(${x.id})">${x.ativo?'Desativar':'Ativar'}</button></td></tr>`).join(''):'<tr><td colspan="6" class="muted" style="text-align:center;padding:24px">Nenhum usuário cadastrado.</td></tr>'}
  </tbody></table></div>`;
}
async function saveUser(e){
  e.preventDefault();if(!isAdmin())return false;
  const nome=$('#un').value.trim(),usuario=$('#uu').value.trim().toLowerCase(),senha=$('#us').value,role=$('#ur').value,limiteCompra=parseMoney($('#ul').value);
  const ed=S.editUser?db.users.find(x=>x.id===S.editUser):null;
  if(!nome||!usuario)return flash('Preencha nome e usuário.','err'),false;
  if(/\s/.test(usuario))return flash('O usuário não pode ter espaços.','err'),false;
  if(role!=='admin'&&role!=='funcionario')return flash('Selecione um perfil de acesso válido.','err'),false;
  if(isNaN(limiteCompra))return flash('Informe um limite mensal de compra válido.','err'),false;
  if(db.users.some(x=>x.usuario===usuario&&(!ed||x.id!==ed.id)))return flash('Este usuário já existe.','err'),false;
  if((!ed||senha)&&senha.length<6)return flash('A senha deve ter pelo menos 6 caracteres.','err'),false;
  if(ed&&String(ed.id)===String(S.user.id)&&role!=='admin')return flash('Não é possível remover seu próprio acesso de administrador.','err'),false;
  if(ed&&ed.role==='admin'&&ed.ativo&&role!=='admin'&&!db.users.some(x=>x.id!==ed.id&&x.role==='admin'&&x.ativo))return flash('O sistema precisa manter pelo menos um administrador ativo.','err'),false;
  if(ed){ed.nome=nome;ed.usuario=usuario;ed.role=role;ed.limiteCompra=role==='funcionario'?limiteCompra:0;if(senha)await setPw(ed,senha);}
  else{const u={id:nextId('user'),nome,usuario,role,ativo:true,limiteCompra:role==='funcionario'?limiteCompra:0};await setPw(u,senha);db.users.push(u);}
  if(!save())return false;
  flash('Usuário salvo.','ok');S.editUser=null;renderTab();return false;
}
function toggleUser(id){
  if(!isAdmin())return;const u=db.users.find(x=>x.id===id);
  if(!u)return;
  if(u.ativo&&String(u.id)===String(S.user.id))return flash('Não é possível desativar seu próprio usuário.','err');
  if(u.ativo&&u.role==='admin'&&!db.users.some(x=>x.id!==u.id&&x.role==='admin'&&x.ativo))return flash('O sistema precisa manter pelo menos um administrador ativo.','err');
  u.ativo=!u.ativo;if(save())renderTab();
}

/* ====== Compras de funcionários ====== */
function employeePurchasesThisMonth(uid){
  const now=new Date();
  return db.purchases.filter(p=>{
    const date=new Date(p.data);
    return String(p.vendedorId)===String(uid)&&date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth();
  });
}
function employeePurchaseSpent(uid){
  return employeePurchasesThisMonth(uid).reduce((sum,p)=>sum+p.total,0);
}
function openEmployeePurchase(){
  if(!S.user||S.user.role!=='funcionario'||!S.user.ativo)return flash('Somente vendedores ativos podem registrar compras.','err');
  S.purchaseDraft=[];showEmployeePurchase();
}
function showEmployeePurchase(){
  const vendedor=db.users.find(u=>String(u.id)===String(S.user.id)&&u.role==='funcionario'&&u.ativo);
  if(!vendedor)return flash('A conta de vendedor não está ativa.','err');
  const total=S.purchaseDraft.reduce((sum,item)=>sum+item.preco*item.qtd,0);
  const limite=vendedor.limiteCompra||0,acumulado=employeePurchaseSpent(vendedor.id),excede=acumulado+total>limite;
  const produtos=db.products.filter(p=>p.estoque>0).sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR'));
  openModal(`<h2>Compra para uso próprio</h2>
  <p class="muted">Vendedor: <b>${esc(vendedor.nome)}</b><br>Limite mensal: <b>${brl(limite)}</b> · Comprado neste mês: <b>${brl(acumulado)}</b></p>
  <form onsubmit="return safe(saveEmployeePurchase,event)">
    <div class="formgrid">
      <label>Produto<select id="purchaseProduct" required>${produtos.map(p=>`<option value="${p.id}">${esc(p.nome)} — ${brl(p.preco)} (${p.estoque} disponíveis)</option>`).join('')}</select></label>
      <label>Quantidade<input id="purchaseQty" type="number" min="1" step="1" value="1" required></label>
      <div class="actions" style="margin:0"><button type="button" class="btn" onclick="addEmployeePurchaseItem()">Adicionar item</button></div>
    </div>
    ${S.purchaseDraft.length?`<div class="card" style="margin-top:14px"><table><thead><tr><th>Produto</th><th>Qtd.</th><th class="num">Subtotal</th><th></th></tr></thead><tbody>
      ${S.purchaseDraft.map((item,index)=>`<tr><td>${esc(item.nome)}</td><td>${item.qtd}</td><td class="num">${brl(item.preco*item.qtd)}</td><td class="num"><button type="button" class="btn sm danger" onclick="removeEmployeePurchaseItem(${index})">Remover</button></td></tr>`).join('')}
    </tbody></table><p class="num"><b>Total da compra: ${brl(total)}</b></p></div>`:'<p class="muted">Adicione os produtos que deseja comprar.</p>'}
    ${excede&&total>0?`<div class="card"><b>Esta compra ultrapassa seu limite mensal.</b><p class="muted">Informe as credenciais de um administrador ativo para autorizar.</p>
      <label>Login do administrador<input id="purchaseAdminUser" required autocomplete="username"></label>
      <label style="margin-top:10px">Senha do administrador<input id="purchaseAdminPassword" type="password" required autocomplete="current-password"></label>
    </div>`:''}
    <div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" ${total?'':'disabled'}>${excede?'Autorizar e registrar compra':'Registrar compra'}</button></div>
  </form>`);
}
function addEmployeePurchaseItem(){
  const id=Number($('#purchaseProduct').value),qtd=Number($('#purchaseQty').value),p=P(id);
  if(!p||!Number.isInteger(qtd)||qtd<1)return flash('Selecione um produto e uma quantidade válida.','err');
  const current=S.purchaseDraft.find(item=>item.id===id),newQty=(current?current.qtd:0)+qtd;
  if(newQty>p.estoque)return flash(`Estoque insuficiente de "${p.nome}". Disponível: ${p.estoque}`,'err');
  if(current)current.qtd=newQty;
  else S.purchaseDraft.push({id:p.id,nome:p.nome,preco:p.preco,qtd});
  showEmployeePurchase();
}
function removeEmployeePurchaseItem(index){
  S.purchaseDraft.splice(index,1);showEmployeePurchase();
}
async function saveEmployeePurchase(e){
  e.preventDefault();
  if(S.purchaseSaving)return false;
  S.purchaseSaving=true;
  try{
    const vendedor=db.users.find(u=>S.user&&String(u.id)===String(S.user.id)&&u.role==='funcionario'&&u.ativo);
    if(!vendedor)return flash('Somente vendedores ativos podem registrar compras.','err'),false;
    if(!S.purchaseDraft.length)return flash('Adicione ao menos um produto.','err'),false;
    const itens=[];
    for(const item of S.purchaseDraft){
      const p=P(item.id);
      if(!p)return flash('Um produto foi removido do cadastro. Feche e refaça a compra.','err'),false;
      if(!Number.isInteger(item.qtd)||item.qtd<1||item.qtd>p.estoque)return flash(`Estoque insuficiente de "${p.nome}". Disponível: ${p.estoque}`,'err'),false;
      itens.push({id:p.id,nome:p.nome,codigo:p.codigo,preco:p.preco,qtd:item.qtd});
    }
    const total=itens.reduce((sum,item)=>sum+item.preco*item.qtd,0);
    const limite=vendedor.limiteCompra||0,acumulado=employeePurchaseSpent(vendedor.id),excede=acumulado+total>limite;
    let aprovador=null;
    if(excede){
      const usuario=$('#purchaseAdminUser').value.trim().toLowerCase(),senha=$('#purchaseAdminPassword').value;
      if(!usuario||!senha)return flash('Informe o login e a senha do administrador para autorizar.','err'),false;
      aprovador=db.users.find(u=>u.usuario===usuario&&u.role==='admin'&&u.ativo);
      if(!aprovador)return flash('Credenciais de administrador inválidas.','err'),false;
      let senhaValida=false;
      try{senhaValida=(await hashPw(senha,aprovador.salt,aprovador.alg))===aprovador.hash;}
      catch(err){return flash('Não foi possível validar a senha do administrador.','err'),false;}
      if(!senhaValida)return flash('Credenciais de administrador inválidas.','err'),false;
    }
    const now=new Date().toISOString(),seq=db.seq.purchase||0;
    const compra={id:nextId('purchase'),data:now,vendedorId:vendedor.id,vendedorNome:vendedor.nome,itens,total,aprovadorId:aprovador?aprovador.id:null,aprovadorNome:aprovador?aprovador.nome:null};
    itens.forEach(item=>{P(item.id).estoque-=item.qtd;});
    db.purchases.push(compra);
    if(!save()){
      itens.forEach(item=>{P(item.id).estoque+=item.qtd;});
      db.purchases.pop();db.seq.purchase=seq;
      return false;
    }
    S.purchaseDraft=[];closeModal();flash('Compra registrada e estoque atualizado.','ok');return false;
  }finally{
    S.purchaseSaving=false;
  }
}
function comprasFuncionariosHTML(){
  const vendedores=db.users.filter(u=>u.role==='funcionario');
  const compras=[...db.purchases].sort((a,b)=>new Date(b.data)-new Date(a.data));
  return `<div class="card"><h2>Limites e compras deste mês</h2><p class="muted">Os limites são individuais e reiniciam a cada mês. Compras registradas descontam os produtos do estoque.</p>
  <table><thead><tr><th>Vendedor</th><th>Limite mensal</th><th>Comprado</th><th>Disponível</th></tr></thead><tbody>
  ${vendedores.length?vendedores.map(u=>{const limite=u.limiteCompra||0,gasto=employeePurchaseSpent(u.id);return `<tr><td>${esc(u.nome)}${u.ativo?'':' (inativo)'}</td><td>${brl(limite)}</td><td>${brl(gasto)}</td><td>${brl(Math.max(0,limite-gasto))}</td></tr>`;}).join(''):'<tr><td colspan="4" class="muted" style="text-align:center;padding:24px">Nenhum vendedor cadastrado.</td></tr>'}
  </tbody></table></div>
  <div class="card"><h2>Histórico de compras</h2><table><thead><tr><th>Data</th><th>Vendedor</th><th>Itens</th><th class="num">Total</th><th>Autorizado por</th></tr></thead><tbody>
  ${compras.length?compras.map(p=>`<tr><td>${dt(p.data)}</td><td>${esc(p.vendedorNome)}</td><td>${p.itens.map(item=>`${esc(item.nome)} × ${item.qtd}`).join('<br>')}</td><td class="num">${brl(p.total)}</td><td>${p.aprovadorNome?esc(p.aprovadorNome):'Dentro do limite'}</td></tr>`).join(''):'<tr><td colspan="5" class="muted" style="text-align:center;padding:24px">Nenhuma compra registrada.</td></tr>'}
  </tbody></table></div>`;
}

/* ====== Backup (admin) ====== */
function backupHTML(){return `<div class="card"><h2>Backup dos dados</h2>
  <p>Os dados (produtos, vendas, compras de funcionários, caixas, usuários e metas) ficam salvos <b>neste navegador, neste computador</b>. Faça backup com frequência e guarde o arquivo em local seguro (ele contém as senhas em formato protegido).</p>
  <h2>Backup de estoque</h2><p class="muted">Salva somente os produtos, códigos, preços e quantidades atuais em estoque.</p>
  <div class="actions" style="justify-content:flex-start"><button class="btn" onclick="exportStockBackup()">Baixar backup de estoque</button>
  <label class="btn" style="cursor:pointer;margin:0">Restaurar estoque<input type="file" accept=".json" hidden onchange="importStockBackup(this)"></label></div>
  <h2>Backup de faturamento</h2><p class="muted">Salva vendas, pagamentos, compras de funcionários e registros de abertura/fechamento de caixa.</p>
  <div class="actions" style="justify-content:flex-start"><button class="btn" onclick="exportSalesBackup()">Baixar backup de faturamento</button>
  <label class="btn" style="cursor:pointer;margin:0">Restaurar faturamento<input type="file" accept=".json" hidden onchange="importSalesBackup(this)"></label></div>
  <h2>Backup completo</h2><p class="muted">Salva todos os dados do sistema, inclusive usuários e senhas protegidas. O arquivo contém informações sensíveis.</p>
  <div class="actions" style="justify-content:flex-start"><button class="btn primary" onclick="exportBackup()">Baixar backup completo</button>
  <label class="btn" style="cursor:pointer;margin:0">Restaurar backup completo<input type="file" accept=".json" hidden onchange="importBackup(this)"></label></div></div>`;}
function downloadBackup(data,name){
  const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));
  a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function exportBackup(){
  downloadBackup(db,`backup-completo-${dstr(new Date())}.json`);
}
function exportStockBackup(){
  downloadBackup({type:'pdv-stock-backup',version:1,exportedAt:new Date().toISOString(),products:db.products.map(p=>({id:p.id,nome:p.nome,codigo:p.codigo,preco:p.preco,estoque:p.estoque}))},`backup-estoque-${dstr(new Date())}.json`);
}
function exportSalesBackup(){
  downloadBackup({type:'pdv-sales-backup',version:1,exportedAt:new Date().toISOString(),sales:db.sales,purchases:db.purchases,cashRegisters:db.cashRegisters},`backup-faturamento-${dstr(new Date())}.json`);
}
function readBackupFile(inp,handler){
  const f=inp.files&&inp.files[0];if(!f)return;
  const r=new FileReader();
  r.onload=()=>{try{handler(JSON.parse(r.result));}catch(e){flash(e&&e.message?e.message:'Arquivo de backup inválido.','err');}};
  r.onerror=()=>flash('Não foi possível ler o arquivo de backup.','err');
  r.readAsText(f);
}
function importStockBackup(inp){
  readBackupFile(inp,data=>{
    if(data.type!=='pdv-stock-backup'||!Array.isArray(data.products)||!data.products.every(p=>Number.isFinite(p.id)&&typeof p.nome==='string'&&typeof p.codigo==='string'&&Number.isFinite(p.preco)&&Number.isInteger(p.estoque)&&p.estoque>=0))throw new Error('Arquivo de backup de estoque inválido.');
    const products=new Map(db.products.map(p=>[p.id,p]));
    for(const entry of data.products){
      const current=products.get(entry.id);
      if(!current||current.codigo!==entry.codigo)throw new Error(`O produto "${entry.nome}" não corresponde ao cadastro atual. Restaure o backup completo para recuperar produtos removidos.`);
    }
    if(!confirm('Isto vai substituir as quantidades em estoque dos produtos correspondentes. Produtos sem correspondência serão mantidos. Continuar?'))return;
    const previous=data.products.map(entry=>[products.get(entry.id),products.get(entry.id).estoque]);
    data.products.forEach(entry=>{products.get(entry.id).estoque=entry.estoque;});
    if(!save()){previous.forEach(([product,stock])=>{product.estoque=stock;});return;}
    flash('Estoque restaurado.','ok');renderTab();
  });
}
function importSalesBackup(inp){
  readBackupFile(inp,data=>{
    if(data.type!=='pdv-sales-backup'||!Array.isArray(data.sales)||!Array.isArray(data.purchases)||!Array.isArray(data.cashRegisters))throw new Error('Arquivo de backup de faturamento inválido.');
    if(!data.sales.every(s=>Number.isFinite(s.id)&&typeof s.data==='string'&&Number.isFinite(s.total)&&Array.isArray(s.itens))||!data.purchases.every(p=>Number.isFinite(p.id)&&typeof p.data==='string'&&Number.isFinite(p.total)&&Array.isArray(p.itens))||!data.cashRegisters.every(c=>Number.isFinite(c.id)&&typeof c.openedAt==='string'&&Number.isFinite(c.openingAmount)))throw new Error('O conteúdo do backup de faturamento está inválido.');
    if(!confirm('Isto vai substituir o faturamento, as compras de funcionários e os registros de caixa atuais. Continuar?'))return;
    const previous={sales:db.sales,purchases:db.purchases,cashRegisters:db.cashRegisters};
    db.sales=data.sales;db.purchases=data.purchases;db.cashRegisters=data.cashRegisters;
    if(!save()){Object.assign(db,previous);return;}
    flash('Faturamento e movimentos de caixa restaurados.','ok');renderTab();
  });
}
function importBackup(inp){
  readBackupFile(inp,d=>{
    if(!Array.isArray(d.users)||!Array.isArray(d.products)||!Array.isArray(d.sales))throw 0;
    if(!d.users.some(u=>u.role==='admin'))throw 0;
    if(!confirm('Isto vai SUBSTITUIR todos os dados atuais pelos do backup. Continuar?'))return;
    d.seq=d.seq||{};d.goals=d.goals||{};d.purchases=Array.isArray(d.purchases)?d.purchases:[];d.cashRegisters=Array.isArray(d.cashRegisters)?d.cashRegisters:[];db=d;if(save()){sess.del();flash('Backup restaurado. Entre novamente.','ok');render();}
  });
}

/* ====== Eventos globais ====== */
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&modalOpen)closeModal();
  if(e.key==='F2'&&S.user&&S.tab==='caixa'&&!modalOpen){e.preventDefault();openPay();}
});
document.addEventListener('click',e=>{
  if(S.tab==='caixa'&&S.user&&!modalOpen&&!/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))setTimeout(()=>{const s=$('#scan');if(s&&!modalOpen)s.focus();},0);
});
window.addEventListener('storage',e=>{
  if(e.key!==KEY)return;db=load();
  if(S.user&&!modalOpen&&['caixa','metas','vendas','produtos','compras'].includes(S.tab))renderTab();
});
render();
